/**
 * Finds the minimum score for each unique key in the input arrays.
 * Ties are broken by the earliest index.
 * Returns the indices in the order of the first appearance of each key.
 *
 * @param {number[]} keys - Array of keys.
 * @param {number[]} scores - Array of scores corresponding to keys.
 * @returns {number[]} - Array of indices for the minimum score of each key, or null if input is invalid.
 */
function firstMinPerKey(keys, scores) {
  // Validate input lengths
  if (keys.length !== scores.length) {
    return null;
  }

  // Create a map to store the minimum score and its index for each key
  // We use a Map to preserve insertion order of keys as they first appear
  const minMap = new Map();

  for (let i = 0; i < keys.length; i++) {
    const key = keys[i];
    const score = scores[i];

    if (!minMap.has(key)) {
      // First time seeing this key, initialize with current score and index
      minMap.set(key, { minScore: score, minIndex: i });
    } else {
      // Compare with existing minimum
      const existing = minMap.get(key);
      if (score < existing.minScore) {
        minMap.set(key, { minScore: score, minIndex: i });
      } else if (score === existing.minScore) {
        // Tie-breaker: earliest index wins
        if (i < existing.minIndex) {
          minMap.set(key, { minScore: score, minIndex: i });
        }
      }
    }
  }

  // Extract the indices in the order of first appearance
  const result = [];
  for (const key of minMap.keys()) {
    result.push(minMap.get(key).minIndex);
  }

  return result;
}

module.exports.firstMinPerKey = firstMinPerKey;

